"""v0.2 feature regression against current bundle. Chromium set_content; memory only."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import json,argparse,os,sys
R=Path(__file__).resolve().parents[1];Q=R/'qa';Q.mkdir(exist_ok=True)
p=argparse.ArgumentParser();p.add_argument('--group',choices=['flow','privacy','recovery','layout','receipt'],required=True);p.add_argument('--static-renderer',action='store_true');args=p.parse_args()
checks=[];errors=[];requests=[]
def check(name,condition):
 if not condition: raise AssertionError(name)
 checks.append(name);print('PASS '+name,flush=True)
def state(page,value,timeout=22000):
 try:page.wait_for_function('(s)=>RetroApp.status.state===s',arg=value,timeout=timeout)
 except Exception as e:
  print('STATE WAIT FAILED',value,str(e),flush=True)
  try:print('ACTUAL',page.evaluate('RetroApp.status'),'ERROR',page.locator('#errorText').inner_text(),'JS ERRORS',errors,flush=True)
  except Exception as detail:print('DIAG FAILED',str(detail),flush=True)
  os._exit(2)
def configure(page):
 page.evaluate('RetroApp.go("admin")');page.locator('#countdownSetting').select_option('0');page.locator('#returnSeconds').select_option('1');page.locator('#showEnabled').check();page.locator('#showDelay').select_option('0');page.locator('#settingsForm button[type=submit]').click();page.evaluate('RetroApp.go("booth")')
def seed(page):
 page.locator('#touchBtn').click();state(page,'recording');page.wait_for_timeout(2200);page.evaluate('RetroApp.stop()');state(page,'idle');return page.evaluate('RetroApp.clips.at(-1).id')
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH') or None,headless=True,args=['--no-sandbox'])
 page=browser.new_page(viewport={'width':1024,'height':768});page.set_default_timeout(8000)
 page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:requests.append(r.url))
 html=(R/'dist/RetroBooth_Prototype.html').read_text()
 if args.static_renderer:
  html=html.replace('(async function () {','const qaOriginalDraw=RetroRenderer.prototype.draw;RetroRenderer.prototype.draw=function(t){if(!this.qaDrawn){qaOriginalDraw.call(this,t);this.qaDrawn=true;}};\n(async function () {',1)
 page.set_content(html);page.wait_for_function('window.RetroApp?.status.ready')
 if args.group=='flow':
  check('default kiosk with one visible guest action',page.locator('.guest-actions button:visible').count()==1)
  check('admin library and receipt preview hidden from guest',page.locator('.site-header').is_hidden() and page.locator('.receipt-column').is_hidden())
  check('privacy notice is visible',page.locator('.privacy-line').is_visible())
  check('no guest stop or playback controls',page.locator('#stopBtn').is_hidden() and page.locator('#playback').is_hidden())
  page.locator('#touchBtn').click();state(page,'recording')
  check('Start is visible but locked; no finish action while recording',page.locator('#touchBtn').is_visible() and page.locator('#touchBtn').is_disabled() and page.locator('#stopBtn').is_hidden())
  page.evaluate('RetroApp.start("touch")');check('repeat start ignored',page.evaluate('RetroApp.status.state==="recording"'))
  state(page,'qr');check('one automatically completed ten-second clip',page.evaluate('RetroApp.clips.length===1 && RetroApp.clips[0].durationMs>=10000 && RetroApp.clips[0].durationMs<12000'))
  check('no automatic playback at completion',not page.locator('#clipDialog').evaluate('(e)=>e.open'))
  check('new clip starts private pending approval',page.evaluate('RetroApp.clips[0].guestPermission==="private" && RetroApp.clips[0].moderation==="pending"'))
  check('printing and upload remain disconnected',page.evaluate('RetroApp.clips[0].printState==="not_connected" && RetroApp.clips[0].uploadState==="not_configured"'))
  state(page,'idle');check('automatic re-arm without a finish click',page.locator('#touchBtn').is_enabled())
  page.locator('#touchBtn').click();state(page,'recording');state(page,'idle',timeout=22000)
  check('second full automatic cycle gets distinct ID and sequence',page.evaluate('RetroApp.clips.length===2 && RetroApp.clips[0].id!==RetroApp.clips[1].id && RetroApp.clips[1].seq===2'))
  check('no navigation to playback or receipts',page.evaluate('RetroApp.status.view==="booth"'))
 elif args.group=='privacy':
  configure(page);id=seed(page)
  page.evaluate('RetroApp.go("show")');check('private clip excluded from show',page.evaluate('RetroApp.showId===null'))
  page.evaluate('(id)=>RetroApp.openGuest(id)',id);check('guest page opens',page.locator('#view-guest').is_visible())
  check('demo cannot download nonexistent video',page.locator('#guestDownload').is_hidden())
  page.locator('#guestHide').click();page.wait_for_function('RetroApp.clips[0].guestPermission==="hidden"')
  check('hide preserves clip and snapshot',page.evaluate('RetroApp.status.clipCount===1') and page.locator('#guestImage').is_visible())
  page.locator('#guestAllow').click();page.wait_for_function('RetroApp.clips[0].guestPermission==="allow"')
  page.evaluate('RetroApp.go("show")');check('guest permission alone is not sufficient',page.evaluate('RetroApp.showId===null'))
  page.evaluate('RetroApp.go("library")');page.get_by_role('button',name='Approve for show',exact=True).click();page.wait_for_function('RetroApp.clips[0].moderation==="approved"')
  page.evaluate('RetroApp.go("show")');check('guest plus staff permission enters show',page.evaluate('(id)=>RetroApp.showId===id',id))
  page.screenshot(path=str(Q/'show-1024.png'),full_page=True)
  # Dispatch an already-bound guest command without navigation, representing a concurrent privacy event.
  page.locator('#guestHide').evaluate('(e)=>e.click()');page.wait_for_function('RetroApp.showId===null')
  check('hiding current show immediately clears its media',page.locator('#showImage').get_attribute('src') is None)
  page.locator('#guestAllow').evaluate('(e)=>e.click()');page.wait_for_function('(id)=>RetroApp.showId===id',arg=id)
  check('hide can be reversed without creating another clip',page.evaluate('RetroApp.status.clipCount===1'))
  page.evaluate('(id)=>RetroApp.openGuest(id)',id);page.set_viewport_size({'width':390,'height':844});page.screenshot(path=str(Q/'guest-390.png'),full_page=True)
  page.locator('#guestDelete').click();check('delete opens separate confirmation',page.locator('#deleteDialog').evaluate('(e)=>e.open'))
  check('delete cannot confirm without acknowledgment',page.locator('#deleteConfirm').is_disabled())
  page.locator('#deleteCancel').click();check('cancel keeps clip',page.evaluate('RetroApp.status.clipCount===1'))
  page.locator('#guestDelete').click();page.keyboard.press('Escape');check('escape keeps clip',page.evaluate('RetroApp.status.clipCount===1') and not page.locator('#deleteDialog').evaluate('(e)=>e.open'))
  page.locator('#guestDelete').click();page.locator('#deleteAck').check();page.screenshot(path=str(Q/'delete-390.png'),full_page=True);page.locator('#deleteConfirm').click();page.wait_for_function('RetroApp.status.clipCount===0')
  check('confirmed deletion removes local clip',page.evaluate('RetroApp.status.clipCount===0'))
  check('deleted route does not display cached snapshot',page.locator('#guestMedia').is_hidden() and page.locator('#guestImage').get_attribute('src') is None)
  check('deleted route has no restore/download controls',page.locator('#guestControls').is_hidden())
  page.evaluate('(id)=>RetroApp.openGuest(id)',id);check('tombstone persists for route in same memory session','DELETED' in page.locator('#guestStatus').inner_text())
  page.evaluate('RetroApp.go("show")');check('deleted clip cannot re-enter show',page.evaluate('RetroApp.showId===null'))
  page.evaluate('RetroApp.go("booth")');newid=seed(page);check('deletion does not reuse receipt number',page.evaluate('RetroApp.clips[0].seq===2') and newid!=id)
 elif args.group=='recovery':
  configure(page);page.evaluate('RetroApp.go("admin")');page.locator('#failSave').check();page.locator('#failPrint').check();page.locator('#offlineSim').check();page.evaluate('RetroApp.go("booth")')
  page.locator('#touchBtn').click();state(page,'recording');page.wait_for_timeout(2200);page.evaluate('RetroApp.stop()');state(page,'error')
  check('failed local save blocks continuous loop',page.evaluate('RetroApp.status.pending && RetroApp.status.clipCount===0'))
  check('no false successful save',page.locator('#errorDialog').evaluate('(e)=>e.open'))
  page.keyboard.press('Escape');check('save recovery cannot be silently dismissed',page.locator('#errorDialog').evaluate('(e)=>e.open'))
  page.locator('#retrySave').click();state(page,'idle')
  check('save retry stores exactly one clip',page.evaluate('RetroApp.status.clipCount===1 && !RetroApp.status.pending'))
  check('print and upload failures stay independent',page.evaluate('RetroApp.clips[0].simulation.print==="simulated_pending" && RetroApp.clips[0].simulation.upload==="simulated_pending"'))
  check('printer offline does not erase local clip',page.locator('#touchBtn').is_enabled())
  page.evaluate('RetroApp.go("admin")');page.locator('#trigger').select_option('both');page.locator('#settingsForm button[type=submit]').click();page.evaluate('RetroApp.go("booth")')
  page.keyboard.press('[');state(page,'recording');page.wait_for_timeout(2200);page.keyboard.press(']')
  check('fixed-time recording does not require or stop on hangup',page.evaluate('RetroApp.status.state==="recording"'))
  page.evaluate('RetroApp.stop()');state(page,'idle')
  check('reset after handset release is ready',page.evaluate('!RetroApp.status.offHook'))
 elif args.group=='receipt':
  configure(page);page.evaluate('RetroApp.go("admin")')
  for style in ['classic','ticket','minimal']:
   page.locator('#receiptStyle').select_option(style);page.wait_for_timeout(100)
   check(style+' template renders bounded receipt',page.locator('#designCanvas').evaluate('(c)=>c.width===384&&c.height>300&&c.height<2000'))
  page.locator('#receiptCaption').fill('HELLO FROM THE EVENT');page.locator('#receiptFooter').fill('KEEP THIS LITTLE MOMENT');page.locator('#eventTitle').fill('<img src=x onerror=alert(1)>');page.locator('#settingsForm button[type=submit]').click()
  check('receipt design saved with event settings',page.evaluate('RetroApp.status.settings.receiptCaption==="HELLO FROM THE EVENT" && RetroApp.status.settings.receiptStyle==="minimal"'))
  check('title does not create HTML elements',page.locator('#screenEvent img').count()==0)
  page.evaluate('RetroApp.go("booth")');id=seed(page)
  check('clip freezes its receipt settings',page.evaluate('RetroApp.clips[0].settings.receiptStyle==="minimal"'))
  page.evaluate('RetroApp.go("admin")');page.locator('#receiptStyle').select_option('ticket');page.locator('#settingsForm button[type=submit]').click()
  check('later design changes do not rewrite old receipt',page.evaluate('RetroApp.clips[0].settings.receiptStyle==="minimal" && RetroApp.status.settings.receiptStyle==="ticket"'))
  page.evaluate('RetroApp.go("library")');page.get_by_role('button',name='View demo',exact=True).click();page.locator('#clipReceiptBtn').click()
  check('original receipt rendered in staff DOM',page.locator('#receiptCanvas').evaluate('(c)=>c.width===384&&c.height>300'))
  receipt=page.locator('#receiptCanvas').evaluate('c=>Array.from(c.getContext("2d").getImageData(0,0,c.width,c.height).data).every((v,i)=>i%4===3?v===255:(v===0||v===255))')
  check('receipt pixels are black and white only',receipt)
  page.locator('#receiptCanvas').evaluate("c=>window.__receiptPNG=c.toDataURL('image/png')")
  import base64
  (Q/'receipt-v02.png').write_bytes(base64.b64decode(page.evaluate('window.__receiptPNG').split(',')[1]))
 elif args.group=='layout':
  configure(page);id=seed(page)
  for width,height in [(1440,1000),(1024,768),(768,1024),(390,844),(320,720)]:
   page.set_viewport_size({'width':width,'height':height})
   for view in ['booth','admin','library','guest','show']:
    if view=='guest':page.evaluate('(id)=>RetroApp.openGuest(id)',id)
    else:page.evaluate('(v)=>RetroApp.go(v)',view)
    page.wait_for_timeout(100)
    check(str(width)+' '+view+' no horizontal overflow',page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'))
    check(str(width)+' '+view+' active view matches',page.evaluate('(v)=>RetroApp.status.view===v',view))
    if (width,view) in [(1024,'booth'),(1440,'admin'),(390,'admin'),(390,'guest')]:page.screenshot(path=str(Q/(view+'-'+str(width)+'.png')),full_page=True)
 check('no JavaScript runtime errors',not errors)
 check('no external HTTP requests',not [x for x in requests if x.startswith(('http:','https:'))])
 (Q/('browser-'+args.group+'.json')).write_text(json.dumps({'group':args.group,'static_renderer':args.static_renderer,'passed':len(checks),'checks':checks,'errors':errors,'external_requests':requests,'scope':'Chromium set_content; opaque origin; memory demo; no native IDB / BLE / cloud / iPad validation'},indent=2))
 print('TOTAL',len(checks),'PASSED',flush=True);browser.close()
